    foreach($m in $ms){
      $t=($m.Groups[2].Value -replace '<[^>]+>','')
      if($t -match '夜兰|璃月|7\.4|加强'){ "T: $t"; "U: $($m.Groups[1].Value)" }
    }
  } else { "no html" }
  Start-Sleep -Milliseconds 800
}"}

